265	// UninstallHooks removes Entire hooks from Factory AI Droid settings.
266	func (f *FactoryAIDroidAgent) UninstallHooks(ctx context.Context) error {
267		// Use repo root to find .factory directory when run from a subdirectory
268		repoRoot, err := paths.WorktreeRoot(ctx)
269		if err != nil {
270			repoRoot = "." // Fallback to CWD if not in a git repo
271		}
272		settingsPath := filepath.Join(repoRoot, ".factory", FactorySettingsFileName)
273		data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
274		if err != nil {
275			return nil //nolint:nilerr // No settings file means nothing to uninstall
276		}
277	
278		var rawSettings map[string]json.RawMessage
279		if err := json.Unmarshal(data, &rawSettings); err != nil {
280			return fmt.Errorf("failed to parse settings.json: %w", err)
281		}
282	
283		// rawHooks preserves unknown hook types
284		var rawHooks map[string]json.RawMessage
285		if hooksRaw, ok := rawSettings["hooks"]; ok {
286			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
287				return fmt.Errorf("failed to parse hooks: %w", err)
288			}
289		}
290		if rawHooks == nil {
291			rawHooks = make(map[string]json.RawMessage)
292		}
293	
294		// Parse only the hook types we need to modify
295		var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse, preCompact []FactoryHookMatcher
296		parseHookType(rawHooks, "SessionStart", &sessionStart)
297		parseHookType(rawHooks, "SessionEnd", &sessionEnd)
298		parseHookType(rawHooks, "Stop", &stop)
299		parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
300		parseHookType(rawHooks, "PreToolUse", &preToolUse)
301		parseHookType(rawHooks, "PostToolUse", &postToolUse)
302		parseHookType(rawHooks, "PreCompact", &preCompact)
303	
304		// Remove Entire hooks from all hook types
305		sessionStart = removeEntireHooks(sessionStart)
306		sessionEnd = removeEntireHooks(sessionEnd)
307		stop = removeEntireHooks(stop)
308		userPromptSubmit = removeEntireHooks(userPromptSubmit)
309		preToolUse = removeEntireHooks(preToolUse)
310		postToolUse = removeEntireHooks(postToolUse)
311		preCompact = removeEntireHooks(preCompact)
312	
313		// Marshal modified hook types back to rawHooks
314		marshalHookType(rawHooks, "SessionStart", sessionStart)
315		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
316		marshalHookType(rawHooks, "Stop", stop)
317		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
318		marshalHookType(rawHooks, "PreToolUse", preToolUse)
319		marshalHookType(rawHooks, "PostToolUse", postToolUse)
320		marshalHookType(rawHooks, "PreCompact", preCompact)
321	
322		// Also remove the metadata deny rule from permissions
323		var rawPermissions map[string]json.RawMessage
324		if permRaw, ok := rawSettings["permissions"]; ok {
325			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
326				// If parsing fails, just skip permissions cleanup
327				rawPermissions = nil
328			}
329		}
330	
331		if rawPermissions != nil {
332			if denyRaw, ok := rawPermissions["deny"]; ok {
333				var denyRules []string
334				if err := json.Unmarshal(denyRaw, &denyRules); err == nil {
335					// Filter out the metadata deny rule
336					filteredRules := make([]string, 0, len(denyRules))
337					for _, rule := range denyRules {
338						if rule != metadataDenyRule {
339							filteredRules = append(filteredRules, rule)
340						}
341					}
342					if len(filteredRules) > 0 {
343						denyJSON, err := json.Marshal(filteredRules)
344						if err == nil {
345							rawPermissions["deny"] = denyJSON
346						}
347					} else {
348						// Remove empty deny array
349						delete(rawPermissions, "deny")
350					}
351				}
352			}
353	
354			// If permissions is empty, remove it entirely
355			if len(rawPermissions) > 0 {
356				permJSON, err := json.Marshal(rawPermissions)
357				if err == nil {
358					rawSettings["permissions"] = permJSON
359				}
360			} else {
361				delete(rawSettings, "permissions")
362			}
363		}
364	
365		// Marshal hooks back (preserving unknown hook types)
366		if len(rawHooks) > 0 {
367			hooksJSON, err := json.Marshal(rawHooks)
368			if err != nil {
369				return fmt.Errorf("failed to marshal hooks: %w", err)
370			}
371			rawSettings["hooks"] = hooksJSON
372		} else {
373			delete(rawSettings, "hooks")
374		}
375	
376		// Write back
377		output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
378		if err != nil {
379			return fmt.Errorf("failed to marshal settings: %w", err)
380		}
381		if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
382			return fmt.Errorf("failed to write settings.json: %w", err)
383		}
384		return nil
385	}
