411	
412	func hookCommandExists(matchers []FactoryHookMatcher, command string) bool {
413		for _, matcher := range matchers {
414			for _, hook := range matcher.Hooks {
415				if hook.Command == command {
416					return true
417				}
418			}
419		}
420		return false
421	}
422	
423	func hookCommandExistsWithMatcher(matchers []FactoryHookMatcher, matcherName, command string) bool {
424		for _, matcher := range matchers {
425			if matcher.Matcher == matcherName {
426				for _, hook := range matcher.Hooks {
427					if hook.Command == command {
428						return true
429					}
430				}
431			}
432		}
433		return false
434	}
435	
436	func addHookToMatcher(matchers []FactoryHookMatcher, matcherName, command string) []FactoryHookMatcher {
437		entry := FactoryHookEntry{Type: "command", Command: command}
438		for i := range matchers {
439			if matchers[i].Matcher == matcherName {
440				matchers[i].Hooks = append(matchers[i].Hooks, entry)
441				return matchers
442			}
443		}
444		return append(matchers, FactoryHookMatcher{Matcher: matcherName, Hooks: []FactoryHookEntry{entry}})
445	}
446	
447	// isEntireHook checks if a command is an Entire hook
448	func isEntireHook(command string) bool {
449		for _, prefix := range entireHookPrefixes {
450			if strings.HasPrefix(command, prefix) {
451				return true
452			}
453		}
454		return false
455	}
456	
457	// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
458	func removeEntireHooks(matchers []FactoryHookMatcher) []FactoryHookMatcher {
459		result := make([]FactoryHookMatcher, 0, len(matchers))
460		for _, matcher := range matchers {
461			filteredHooks := make([]FactoryHookEntry, 0, len(matcher.Hooks))
462			for _, hook := range matcher.Hooks {
463				if !isEntireHook(hook.Command) {
464					filteredHooks = append(filteredHooks, hook)
465				}
466			}
467			// Only keep the matcher if it has hooks remaining
468			if len(filteredHooks) > 0 {
469				matcher.Hooks = filteredHooks
470				result = append(result, matcher)
471			}
472		}
473		return result
474	}
