681	// handleLifecycleSubagentEnd handles subagent end: detects changes, saves task checkpoint.
682	func handleLifecycleSubagentEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
683		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
684		if event.SubagentType == "" && event.TaskDescription == "" {
685			// Extract subagent type and description from tool input
686			event.SubagentType, event.TaskDescription = ParseSubagentTypeAndDescription(event.ToolInput)
687		}
688	
689		// Determine subagent transcript path
690		transcriptDir := filepath.Dir(event.SessionRef)
691		var subagentTranscriptPath string
692		if event.SubagentID != "" {
693			subagentTranscriptPath = AgentTranscriptPath(transcriptDir, event.SubagentID)
694			if !fileExists(subagentTranscriptPath) {
695				subagentTranscriptPath = ""
696			}
697		}
698	
699		// Log context
700		subagentEndAttrs := []any{
701			slog.String("event", event.Type.String()),
702			slog.String("session_id", event.SessionID),
703			slog.String("tool_use_id", event.ToolUseID),
704		}
705		if event.SubagentID != "" {
706			subagentEndAttrs = append(subagentEndAttrs, slog.String("agent_id", event.SubagentID))
707		}
708		if subagentTranscriptPath != "" {
709			subagentEndAttrs = append(subagentEndAttrs, slog.String("subagent_transcript", subagentTranscriptPath))
710		}
711		logging.Info(logCtx, "subagent completed", subagentEndAttrs...)
712	
713		// Extract modified files from hook payload and/or subagent transcript
714		var modifiedFiles []string
715		modifiedFiles = append(modifiedFiles, event.ModifiedFiles...)
716		if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
717			transcriptToScan := event.SessionRef
718			if subagentTranscriptPath != "" {
719				transcriptToScan = subagentTranscriptPath
720			}
721			if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptToScan, 0); fileErr != nil {
722				logging.Warn(logCtx, "failed to extract modified files from subagent",
723					slog.String("error", fileErr.Error()))
724			} else {
725				modifiedFiles = mergeUnique(modifiedFiles, files)
726			}
727		}
728	
729		// Load pre-task state and detect file changes.
730		// If no pre-task state exists (agent doesn't support pre-task hook), fall back
731		// to the session's pre-prompt state. Without either, DetectFileChanges receives
732		// nil and treats ALL untracked files as new — which would create spurious task
733		// checkpoints for pre-existing untracked files (e.g., .github/hooks/entire.json).
734		preState, err := LoadPreTaskState(ctx, event.ToolUseID)
735		if err != nil {
736			logging.Warn(logCtx, "failed to load pre-task state",
737				slog.String("error", err.Error()))
738		}
739		var preUntrackedFiles []string
740		if preState != nil {
741			preUntrackedFiles = preState.PreUntrackedFiles()
742		}
743		changes, err := DetectFileChanges(ctx, preUntrackedFiles)
744		if err != nil {
745			logging.Warn(logCtx, "failed to compute file changes",
746				slog.String("error", err.Error()))
747		}
748	
749		// Get worktree root and normalize paths
750		repoRoot, err := paths.WorktreeRoot(ctx)
751		if err != nil {
752			return fmt.Errorf("failed to get worktree root: %w", err)
753		}
754	
755		relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
756		var relNewFiles, relDeletedFiles []string
757		if changes != nil {
758			relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
759			relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)

