55	// droidSettings represents the ~/.factory/settings.json structure used for
56	// BYOK (Bring Your Own Key) configuration.
57	type droidSettings struct {
58		CustomModels []droidCustomModel `json:"customModels,omitempty"`
59	}
60	
61	type droidCustomModel struct {
62		DisplayName    string `json:"displayName"`
63		Model          string `json:"model"`
64		BaseURL        string `json:"baseUrl"`
65		APIKey         string `json:"apiKey"`
66		Provider       string `json:"provider"`
67		MaxOutputToken int    `json:"maxOutputTokens"`
68	}
