70	const (
71		// Droid v0.63+ expects custom model selection using custom:<model-id>.
72		// The displayName in settings is not accepted by --model.
73		droidCustomModelDisplayName = "claude-haiku-custom"
74		droidCustomModelBaseID      = "claude-haiku-4-5-20251001"
75		defaultDroidModel           = "custom:" + droidCustomModelBaseID
76	)
