82	func (d *Droid) Bootstrap() error {
83		apiKey := os.Getenv("ANTHROPIC_API_KEY")
84		if apiKey == "" {
85			return nil
86		}
87	
88		home, err := os.UserHomeDir()
89		if err != nil {
90			return fmt.Errorf("get home dir: %w", err)
91		}
92		dir := filepath.Join(home, ".factory")
93		if err := os.MkdirAll(dir, 0o755); err != nil {
94			return fmt.Errorf("mkdir %s: %w", dir, err)
95		}
96	
97		settingsPath := filepath.Join(dir, "settings.json")
98	
99		// Read existing settings to merge (hooks may already be configured
100		// in the repo-local .factory/settings.json, but the global config
101		// at ~/.factory/settings.json might have other pre-existing entries).
102		var settings droidSettings
103		if data, readErr := os.ReadFile(settingsPath); readErr == nil {
104			// Best-effort merge: ignore parse errors and start fresh
105			_ = json.Unmarshal(data, &settings)
106		}
107	
108		// Replace or add the BYOK model entry.
109		byokModel := droidCustomModel{
110			DisplayName:    droidCustomModelDisplayName,
111			Model:          droidCustomModelBaseID,
112			BaseURL:        "https://api.anthropic.com",
113			APIKey:         apiKey,
114			Provider:       "anthropic",
115			MaxOutputToken: 8192,
116		}
117	
118		found := false
119		for i, m := range settings.CustomModels {
120			if m.Model == byokModel.Model {
121				settings.CustomModels[i] = byokModel
122				found = true
123				break
124			}
125		}
126		if !found {
127			settings.CustomModels = append(settings.CustomModels, byokModel)
128		}
129	
130		data, err := json.MarshalIndent(settings, "", "  ")
131		if err != nil {
132			return fmt.Errorf("marshal settings: %w", err)
133		}
134		return os.WriteFile(settingsPath, data, 0o644)
135	}
